import { getState, setState, showToast } from '../services/state.js';
import { ApiService } from '../services/api.js';
import { exportDatabaseJSON } from '../services/db.js';

export function renderSettings() {
  const { currentUser } = getState();
  const name = currentUser ? (currentUser.full_name || currentUser.email.split('@')[0]) : 'Clinical Pathologist';
  const email = currentUser ? currentUser.email : 'No user logged in';
  const license = currentUser ? (currentUser.license_id || '') : '';
  const institution = currentUser ? (currentUser.institution || '') : '';
  const role = currentUser
    ? (currentUser.role ? `Consultant ${currentUser.role.charAt(0).toUpperCase() + currentUser.role.slice(1)}` : 'Consultant Pathologist')
    : 'Consultant Pathologist';

  const avatarUrl = `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=38bdf8&color=0b172e&bold=true&size=128`;

  return `
    <div id="page-profile" class="page-content">
      <div class="page-header">
        <div>
          <h1 class="page-title">Doctor Credentials &amp; Profile</h1>
          <p class="page-subtitle">Manage medical license, hospital institution settings, and account security</p>
        </div>
      </div>

      <div style="display:grid; grid-template-columns: 300px 1fr; gap:1.8rem; align-items:start;">
        <!-- Left: Live Profile Card -->
        <div style="background:var(--card-bg); border:1px solid var(--border-color); border-radius:var(--radius-lg); padding:2rem; text-align:center;">
          <img id="prof-avatar" src="${avatarUrl}" alt="Doctor Avatar"
            style="width:110px; height:110px; border-radius:50%; border:3px solid var(--primary-light); margin:0 auto 1.2rem; object-fit:cover;">
          <h2 style="font-size:1.3rem; font-weight:800; color:var(--text-main);" id="prof-name">${name}</h2>
          <div style="font-size:0.85rem; color:var(--primary-light); font-weight:600; margin-top:0.2rem;" id="prof-role">${role}</div>
          <div style="font-size:0.78rem; color:var(--text-subtle); margin-top:0.4rem;" id="prof-id">License: ${license || 'Not specified'}</div>

          <div style="margin-top:1.5rem; padding-top:1.2rem; border-top:1px solid var(--border-color); font-size:0.82rem; color:var(--text-muted);">
            <div id="prof-institution" style="font-weight:600; color:var(--text-main);">${institution || 'PathoAI Medical Center'}</div>
            <div id="prof-email" style="margin-top:0.2rem;">${email}</div>
          </div>

          <!-- Security badge -->
          <div style="margin-top:1.5rem; padding:0.6rem 0.8rem; background:rgba(56,189,248,0.08); border:1px solid rgba(56,189,248,0.2); border-radius:var(--radius-sm);">
            <i class="fas fa-shield-alt" style="color:#38bdf8; margin-right:0.4rem;"></i>
            <span style="font-size:0.78rem; color:#38bdf8; font-weight:600;">Secured Account</span>
          </div>
        </div>

        <!-- Right: Settings & Controls -->
        <div style="display:flex; flex-direction:column; gap:1.5rem;">

          <!-- Update Profile Form -->
          <div style="background:var(--card-bg); border:1px solid var(--border-color); border-radius:var(--radius-lg); padding:2rem;">
            <h3 style="font-size:1.15rem; font-weight:700; color:var(--text-main); margin-bottom:0.4rem;">
              <i class="fas fa-user-md" style="color:var(--primary-light); margin-right:0.5rem;"></i>Update Credentials
            </h3>
            <p style="font-size:0.82rem; color:var(--text-muted); margin-bottom:1.5rem;">
              Changes are saved directly to your doctor record in MongoDB.
            </p>
            <div id="profile-save-error" style="display:none; color:#f87171; font-size:0.85rem; margin-bottom:1rem; padding:0.65rem 0.9rem; background:rgba(248,113,113,0.1); border:1px solid rgba(248,113,113,0.3); border-radius:var(--radius-sm);"></div>
            <div id="profile-save-success" style="display:none; color:#4ade80; font-size:0.85rem; margin-bottom:1rem; padding:0.65rem 0.9rem; background:rgba(74,222,128,0.1); border:1px solid rgba(74,222,128,0.3); border-radius:var(--radius-sm);"></div>

            <form onsubmit="event.preventDefault(); window.PathoApp.saveProfileSettings();">
              <div class="input-wrap">
                <i class="fas fa-user-md"></i>
                <input type="text" id="edit-prof-name" value="${name}" placeholder="Full Doctor Name (Dr. ...)">
              </div>

              <div class="input-wrap">
                <i class="fas fa-id-card"></i>
                <input type="text" id="edit-prof-lic" value="${license}" placeholder="Medical License ID">
              </div>

              <div class="input-wrap">
                <i class="fas fa-hospital"></i>
                <input type="text" id="edit-prof-inst" value="${institution}" placeholder="Hospital / Medical Institution">
              </div>

              <div class="input-wrap">
                <i class="fas fa-envelope"></i>
                <input type="email" id="edit-prof-email" value="${email}" disabled style="opacity:0.6; cursor:not-allowed;">
              </div>

              <div style="margin-top:1.5rem;">
                <button type="submit" id="btn-save-profile" class="btn-primary" style="width:auto;">
                  <i class="fas fa-save"></i>
                  <span id="save-profile-btn-text">Save Profile</span>
                </button>
              </div>
            </form>
          </div>

          <!-- Change Password Form -->
          <div style="background:var(--card-bg); border:1px solid var(--border-color); border-radius:var(--radius-lg); padding:2rem;">
            <h3 style="font-size:1.15rem; font-weight:700; color:var(--text-main); margin-bottom:0.4rem;">
              <i class="fas fa-lock" style="color:var(--primary-light); margin-right:0.5rem;"></i>Change Password
            </h3>
            <p style="font-size:0.82rem; color:var(--text-muted); margin-bottom:1.5rem;">
              Minimum 8 characters required. Your current session will remain active.
            </p>
            <div id="chgpwd-error" style="display:none; color:#f87171; font-size:0.85rem; margin-bottom:1rem; padding:0.65rem 0.9rem; background:rgba(248,113,113,0.1); border:1px solid rgba(248,113,113,0.3); border-radius:var(--radius-sm);"></div>
            <div id="chgpwd-success" style="display:none; color:#4ade80; font-size:0.85rem; margin-bottom:1rem; padding:0.65rem 0.9rem; background:rgba(74,222,128,0.1); border:1px solid rgba(74,222,128,0.3); border-radius:var(--radius-sm);"></div>

            <form onsubmit="event.preventDefault(); window.PathoApp.changePassword();">
              <div class="input-wrap" style="position:relative;">
                <i class="fas fa-lock"></i>
                <input type="password" id="chg-current-pass" placeholder="Current Password" autocomplete="current-password">
                <button type="button" class="pwd-toggle" onclick="window.PathoApp._togglePwd('chg-current-pass', this)" tabindex="-1"
                  style="position:absolute; right:0.9rem; top:50%; transform:translateY(-50%); background:none; border:none; color:var(--text-muted); cursor:pointer; padding:0.2rem;">
                  <i class="fas fa-eye"></i>
                </button>
              </div>

              <div class="input-wrap" style="position:relative;">
                <i class="fas fa-lock"></i>
                <input type="password" id="chg-new-pass" placeholder="New Password (min 8 chars)" autocomplete="new-password" oninput="window.PathoApp._updatePwdStrength(this.value, 'chg-strength')">
                <button type="button" class="pwd-toggle" onclick="window.PathoApp._togglePwd('chg-new-pass', this)" tabindex="-1"
                  style="position:absolute; right:0.9rem; top:50%; transform:translateY(-50%); background:none; border:none; color:var(--text-muted); cursor:pointer; padding:0.2rem;">
                  <i class="fas fa-eye"></i>
                </button>
              </div>
              <div id="chg-strength" style="height:4px; border-radius:2px; margin:-0.8rem 0 1rem 0; transition:all 0.3s;"></div>

              <div class="input-wrap" style="position:relative;">
                <i class="fas fa-lock"></i>
                <input type="password" id="chg-confirm-pass" placeholder="Confirm New Password" autocomplete="new-password">
                <button type="button" class="pwd-toggle" onclick="window.PathoApp._togglePwd('chg-confirm-pass', this)" tabindex="-1"
                  style="position:absolute; right:0.9rem; top:50%; transform:translateY(-50%); background:none; border:none; color:var(--text-muted); cursor:pointer; padding:0.2rem;">
                  <i class="fas fa-eye"></i>
                </button>
              </div>

              <div style="margin-top:1.5rem;">
                <button type="submit" id="btn-change-pwd" class="btn-primary" style="width:auto; background:linear-gradient(135deg,#6366f1,#8b5cf6);">
                  <i class="fas fa-key"></i>
                  <span id="change-pwd-btn-text">Change Password</span>
                </button>
              </div>
            </form>
          </div>

          <!-- Database Management -->
          <div style="background:var(--card-bg); border:1px solid var(--border-color); border-radius:var(--radius-lg); padding:2rem;">
            <h3 style="font-size:1.15rem; font-weight:700; color:#fff; margin-bottom:0.5rem;">
              <i class="fas fa-database" style="color:var(--primary-light); margin-right:0.4rem;"></i>
              Database Integration &amp; Backups
            </h3>
            <p style="font-size:0.85rem; color:var(--text-muted); margin-bottom:1.2rem;">
              Export all patient records and diagnostic metrics directly from MongoDB.
            </p>
            <div style="display:flex; gap:1rem; flex-wrap:wrap;">
              <button class="btn-secondary" onclick="window.PathoApp.exportDatabaseBackup()">
                <i class="fas fa-download"></i> Export Database JSON Backup
              </button>
            </div>
          </div>

        </div>
      </div>
    </div>
  `;
}

export function initSettingsEvents() {
  // ── Password show/hide toggle ─────────────────────────────────────────────
  window.PathoApp._togglePwd = (inputId, btn) => {
    const input = document.getElementById(inputId);
    if (!input) return;
    const isHidden = input.type === 'password';
    input.type = isHidden ? 'text' : 'password';
    const icon = btn.querySelector('i');
    if (icon) {
      icon.className = isHidden ? 'fas fa-eye-slash' : 'fas fa-eye';
    }
  };

  // ── Password strength indicator ───────────────────────────────────────────
  window.PathoApp._updatePwdStrength = (password, barId) => {
    const bar = document.getElementById(barId);
    if (!bar) return;
    let score = 0;
    if (password.length >= 8) score++;
    if (password.length >= 12) score++;
    if (/[A-Z]/.test(password)) score++;
    if (/[0-9]/.test(password)) score++;
    if (/[^A-Za-z0-9]/.test(password)) score++;

    const colors = ['#ef4444', '#f97316', '#eab308', '#22c55e', '#16a34a'];
    const widths = ['20%', '40%', '60%', '80%', '100%'];
    bar.style.background = colors[score - 1] || '#374151';
    bar.style.width = score > 0 ? widths[score - 1] : '0';
  };

  // ── Save Profile ──────────────────────────────────────────────────────────
  window.PathoApp.saveProfileSettings = async () => {
    const nameEl = document.getElementById('edit-prof-name');
    const licEl = document.getElementById('edit-prof-lic');
    const instEl = document.getElementById('edit-prof-inst');
    const errorEl = document.getElementById('profile-save-error');
    const successEl = document.getElementById('profile-save-success');
    const btn = document.getElementById('btn-save-profile');
    const btnText = document.getElementById('save-profile-btn-text');

    if (errorEl) { errorEl.style.display = 'none'; errorEl.textContent = ''; }
    if (successEl) { successEl.style.display = 'none'; successEl.textContent = ''; }

    const name = nameEl ? nameEl.value.trim() : '';
    const lic = licEl ? licEl.value.trim() : '';
    const inst = instEl ? instEl.value.trim() : '';

    if (!name || name.length < 2) {
      if (errorEl) { errorEl.textContent = 'Full name must be at least 2 characters.'; errorEl.style.display = 'block'; }
      return;
    }

    if (btn) btn.disabled = true;
    if (btnText) btnText.textContent = 'Saving…';

    try {
      // Call PUT /auth/me to persist to users collection in MongoDB
      const updatedUser = await ApiService.updateProfile({
        full_name: name,
        license_id: lic,
        institution: inst
      });

      // Update app state with returned user data
      const { currentUser } = getState();
      const mergedUser = {
        ...currentUser,
        full_name: updatedUser.full_name || name,
        institution: updatedUser.institution || inst,
        license_id: updatedUser.license_id || lic,
      };
      setState({ currentUser: mergedUser });

      // Update profile card DOM immediately
      const profName = document.getElementById('prof-name');
      const profInst = document.getElementById('prof-institution');
      const profId = document.getElementById('prof-id');
      const profAvatar = document.getElementById('prof-avatar');
      const hdrName = document.getElementById('hdr-name');
      const hdrAvatar = document.getElementById('hdr-avatar');

      if (profName) profName.textContent = updatedUser.full_name || name;
      if (profInst) profInst.textContent = updatedUser.institution || inst || 'PathoAI Medical Center';
      if (profId) profId.textContent = `License: ${updatedUser.license_id || lic || 'Not specified'}`;

      // Refresh avatar with new name
      const encodedName = encodeURIComponent(updatedUser.full_name || name);
      const newAvatarUrl = `https://ui-avatars.com/api/?name=${encodedName}&background=38bdf8&color=0b172e&bold=true&size=128`;
      if (profAvatar) profAvatar.src = newAvatarUrl;
      if (hdrName) hdrName.textContent = updatedUser.full_name || name;
      if (hdrAvatar) hdrAvatar.src = newAvatarUrl;

      if (successEl) { successEl.textContent = '✓ Profile saved to MongoDB successfully!'; successEl.style.display = 'block'; }
      showToast('Profile credentials saved to MongoDB!', 'success');

    } catch (err) {
      const msg = err.message || 'Failed to save profile. Please try again.';
      if (errorEl) { errorEl.textContent = msg; errorEl.style.display = 'block'; }
      showToast(msg, 'error');
    } finally {
      if (btn) btn.disabled = false;
      if (btnText) btnText.textContent = 'Save Profile';
    }
  };

  // ── Change Password ───────────────────────────────────────────────────────
  window.PathoApp.changePassword = async () => {
    const currentPassEl = document.getElementById('chg-current-pass');
    const newPassEl = document.getElementById('chg-new-pass');
    const confirmPassEl = document.getElementById('chg-confirm-pass');
    const errorEl = document.getElementById('chgpwd-error');
    const successEl = document.getElementById('chgpwd-success');
    const btn = document.getElementById('btn-change-pwd');
    const btnText = document.getElementById('change-pwd-btn-text');

    if (errorEl) { errorEl.style.display = 'none'; errorEl.textContent = ''; }
    if (successEl) { successEl.style.display = 'none'; successEl.textContent = ''; }

    const currentPass = currentPassEl ? currentPassEl.value : '';
    const newPass = newPassEl ? newPassEl.value : '';
    const confirmPass = confirmPassEl ? confirmPassEl.value : '';

    if (!currentPass) {
      if (errorEl) { errorEl.textContent = 'Please enter your current password.'; errorEl.style.display = 'block'; }
      return;
    }
    if (!newPass || newPass.length < 8) {
      if (errorEl) { errorEl.textContent = 'New password must be at least 8 characters.'; errorEl.style.display = 'block'; }
      return;
    }
    if (newPass !== confirmPass) {
      if (errorEl) { errorEl.textContent = 'New passwords do not match.'; errorEl.style.display = 'block'; }
      return;
    }

    if (btn) btn.disabled = true;
    if (btnText) btnText.textContent = 'Changing…';

    try {
      const res = await ApiService.changePassword(currentPass, newPass);
      if (successEl) { successEl.textContent = `✓ ${res.msg || 'Password changed successfully.'}`;  successEl.style.display = 'block'; }
      showToast('Password changed successfully!', 'success');
      // Clear fields
      if (currentPassEl) currentPassEl.value = '';
      if (newPassEl) { newPassEl.value = ''; }
      if (confirmPassEl) confirmPassEl.value = '';
      // Reset strength bar
      const bar = document.getElementById('chg-strength');
      if (bar) { bar.style.background = ''; bar.style.width = '0'; }
    } catch (err) {
      const msg = err.message || 'Failed to change password. Please check your current password.';
      if (errorEl) { errorEl.textContent = msg; errorEl.style.display = 'block'; }
    } finally {
      if (btn) btn.disabled = false;
      if (btnText) btnText.textContent = 'Change Password';
    }
  };

  // ── Export Database Backup ───────────────────────────────────────────────
  window.PathoApp.exportDatabaseBackup = async () => {
    try {
      await exportDatabaseJSON();
      showToast('Database JSON backup downloaded!', 'success');
    } catch (err) {
      showToast('Database export failed: ' + err.message, 'error');
    }
  };
}
